-- --------------------------------------------------------
-- Table structure for table `pos_orders`
-- --------------------------------------------------------
DROP TABLE IF EXISTS `pos_orders`;
CREATE TABLE `pos_orders` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `order_number` varchar(255) NOT NULL,
  `type` enum('dine-in','take-out','delivery') NOT NULL DEFAULT 'dine-in',
  `items` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`items`)),
  `total` decimal(10,2) NOT NULL,
  `status` enum('pending','preparing','completed') NOT NULL DEFAULT 'pending',
  `payment_method` varchar(255) DEFAULT NULL,
  `paid_amount` decimal(10,2) NOT NULL DEFAULT 0.00,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `pos_orders_order_number_unique` (`order_number`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- --------------------------------------------------------
-- Table structure for table `print_jobs`
-- --------------------------------------------------------
DROP TABLE IF EXISTS `print_jobs`;
CREATE TABLE `print_jobs` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `job_uuid` char(36) NOT NULL,
  `sale_id` bigint(20) unsigned DEFAULT NULL,
  `order_id` bigint(20) unsigned DEFAULT NULL,
  `order_number` varchar(255) NOT NULL,
  `branch_id` bigint(20) unsigned NOT NULL,
  `terminal_id` varchar(255) DEFAULT NULL,
  `job_type` varchar(30) NOT NULL DEFAULT 'receipt',
  `paper_width` int(11) NOT NULL DEFAULT 80,
  `status` varchar(20) NOT NULL DEFAULT 'pending',
  `receipt_data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`receipt_data`)),
  `formatted_text` longtext DEFAULT NULL,
  `raw_escpos_base64` longtext DEFAULT NULL,
  `attempts` int(11) NOT NULL DEFAULT 0,
  `last_error` text DEFAULT NULL,
  `reprint_reason` varchar(255) DEFAULT NULL,
  `reprinted_by` bigint(20) unsigned DEFAULT NULL,
  `printed_at` timestamp NULL DEFAULT NULL,
  `idempotency_key` varchar(255) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `print_jobs_job_uuid_unique` (`job_uuid`),
  KEY `print_jobs_sale_id_foreign` (`sale_id`),
  KEY `print_jobs_order_id_foreign` (`order_id`),
  KEY `print_jobs_branch_id_foreign` (`branch_id`),
  KEY `print_jobs_reprinted_by_foreign` (`reprinted_by`),
  KEY `print_jobs_order_number_index` (`order_number`),
  KEY `print_jobs_terminal_id_index` (`terminal_id`),
  KEY `print_jobs_job_type_index` (`job_type`),
  KEY `print_jobs_status_index` (`status`),
  KEY `print_jobs_printed_at_index` (`printed_at`),
  KEY `print_jobs_idempotency_key_index` (`idempotency_key`),
  CONSTRAINT `print_jobs_branch_id_foreign` FOREIGN KEY (`branch_id`) REFERENCES `branches` (`id`) ON DELETE CASCADE,
  CONSTRAINT `print_jobs_order_id_foreign` FOREIGN KEY (`order_id`) REFERENCES `orders` (`id`) ON DELETE SET NULL,
  CONSTRAINT `print_jobs_reprinted_by_foreign` FOREIGN KEY (`reprinted_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `print_jobs_sale_id_foreign` FOREIGN KEY (`sale_id`) REFERENCES `sales` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=33 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

