  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `product_addon_groups_product_id_addon_group_id_unique` (`product_id`,`addon_group_id`),
  KEY `product_addon_groups_addon_group_id_foreign` (`addon_group_id`),
