  PRIMARY KEY (`id`),
  KEY `product_addons_ingredient_id_foreign` (`ingredient_id`),
  KEY `product_addons_product_id_is_active_index` (`product_id`,`is_active`),
  KEY `product_addons_addon_id_foreign` (`addon_id`),
  CONSTRAINT `product_addons_addon_id_foreign` FOREIGN KEY (`addon_id`) REFERENCES `add_ons` (`id`) ON DELETE CASCADE,
  CONSTRAINT `product_addons_ingredient_id_foreign` FOREIGN KEY (`ingredient_id`) REFERENCES `ingredients` (`id`) ON DELETE SET NULL,
  CONSTRAINT `product_addons_product_id_foreign` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`) ON DELETE SET NULL
