  `profile_photo_path` varchar(2048) DEFAULT NULL,
  `mobile_number` varchar(255) DEFAULT NULL,
  `email_verified_at` timestamp NULL DEFAULT NULL,
  `phone_verified_at` timestamp NULL DEFAULT NULL,
  `password` varchar(255) NOT NULL,
  `must_change_password` tinyint(1) NOT NULL DEFAULT 0,
  `two_factor_secret` text DEFAULT NULL,
  `two_factor_recovery_codes` text DEFAULT NULL,
  `two_factor_confirmed_at` timestamp NULL DEFAULT NULL,
  `remember_token` varchar(100) DEFAULT NULL,
  `last_notifications_read_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `role` varchar(255) NOT NULL DEFAULT 'admin',
  `account_status` varchar(30) NOT NULL DEFAULT 'active',
  `status_reason` text DEFAULT NULL,
  `restricted_at` timestamp NULL DEFAULT NULL,
  `suspended_at` timestamp NULL DEFAULT NULL,
  `deactivated_at` timestamp NULL DEFAULT NULL,
  `cod_restricted` tinyint(1) NOT NULL DEFAULT 0,
  `cod_restriction_reason` varchar(255) DEFAULT NULL,
  `cod_restriction_source` varchar(20) DEFAULT NULL,
  `cod_restricted_at` timestamp NULL DEFAULT NULL,
  `cod_restriction_expires_at` timestamp NULL DEFAULT NULL,
  `cod_restricted_by` bigint(20) unsigned DEFAULT NULL,
  `risk_level_override` varchar(20) DEFAULT NULL,
  `branch_id` bigint(20) unsigned DEFAULT NULL,
  `status_changed_by` bigint(20) unsigned DEFAULT NULL,
  `is_order_restricted` tinyint(1) NOT NULL DEFAULT 0,
  `consecutive_cancellations` int(10) unsigned NOT NULL DEFAULT 0,
  `restriction_source` varchar(20) DEFAULT NULL,
  `restriction_reason` text DEFAULT NULL,
  `restriction_removed_at` timestamp NULL DEFAULT NULL,
  `restriction_removed_by` bigint(20) unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `users_email_unique` (`email`),
  KEY `users_branch_id_foreign` (`branch_id`),
  KEY `users_status_changed_by_foreign` (`status_changed_by`),
  KEY `users_account_status_index` (`account_status`),
  KEY `users_restriction_removed_by_foreign` (`restriction_removed_by`),
  CONSTRAINT `users_branch_id_foreign` FOREIGN KEY (`branch_id`) REFERENCES `branches` (`id`) ON DELETE SET NULL,
  CONSTRAINT `users_restriction_removed_by_foreign` FOREIGN KEY (`restriction_removed_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `users_status_changed_by_foreign` FOREIGN KEY (`status_changed_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=26 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

