  `quantity` decimal(15,4) NOT NULL,
  `unit` varchar(255) NOT NULL,
  `cost_at_loss` decimal(15,4) NOT NULL,
  `reason` varchar(255) NOT NULL,
  `notes` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `wastages_branch_id_foreign` (`branch_id`),
  KEY `wastages_user_id_foreign` (`user_id`),
  KEY `wastages_wastable_type_wastable_id_index` (`wastable_type`,`wastable_id`),
  CONSTRAINT `wastages_branch_id_foreign` FOREIGN KEY (`branch_id`) REFERENCES `branches` (`id`) ON DELETE CASCADE,
  CONSTRAINT `wastages_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
